                "shared": {
                    "$id": "https://example.com/shared",
                    "$defs": {"fallback": {"$dynamicAnchor": "choice"}},
                    "$dynamicRef": "#choice"
                },
                "safe": {
                    "$id": "https://example.com/safe",
                    "$ref": "https://example.com/shared",
                    "$defs": {"choice": {"$dynamicAnchor": "choice"}}
