+            std::fs::File::open(parent)?.sync_all().context("sync checkpoint directory")?;
+            Ok(())
+        })();
+        if result.is_err() {
+            let _ = std::fs::remove_file(&temporary);
+        }
+        result
+    }).await.context("checkpoint publication task failed")?
