//! Execution Agents
//!
//! Agents that can execute code and commands with sandboxing.
//! These have SecurityProfiles and process management.

mod base;
mod golang;
mod javascript;
mod python;
mod rust;
mod shell;

pub use base::ExecutionAgent;
pub use golang::GoExecutor;
pub use javascript::JavaScriptExecutor;
pub use python::PythonExecutor;
pub use rust::RustExecutor;
pub use shell::ShellExecutor;

use std::collections::HashMap;
use std::sync::LazyLock;

/// All available execution agents
#[allow(clippy::type_complexity)]
pub static EXECUTION_AGENTS: LazyLock<HashMap<&'static str, fn() -> Box<dyn super::UnifiedAgent>>> =
    LazyLock::new(|| {
        let mut m: HashMap<&'static str, fn() -> Box<dyn super::UnifiedAgent>> = HashMap::new();
        m.insert("python-executor", || Box::new(PythonExecutor::new()));
        m.insert("rust-executor", || Box::new(RustExecutor::new()));
        m.insert(
            "javascript-executor",
            || Box::new(JavaScriptExecutor::new()),
        );
        m.insert("go-executor", || Box::new(GoExecutor::new()));
        m.insert("shell-executor", || Box::new(ShellExecutor::new()));
        m
    });
        "agent_type": agent_type,
        "operation": operation,
        "stdout": stdout,
        "stderr": stderr,
        "exit_code": exit_code,
        "success": success,
        "error": (!success).then(|| format!("child exited with status {exit_code}")),
    })
}

pub struct UnifiedExecutionService;

impl UnifiedExecutionService {
    pub const SERVICE_NAME: &'static str = "org.dbusmcp.Agent.UnifiedExecution";
    pub const OBJECT_PATH: &'static str = "/org/dbusmcp/Agent/UnifiedExecution";

    async fn require_root(
        connection: &Connection,
        header: &Header<'_>,
    ) -> Result<(), zbus::fdo::Error> {
        let sender = header
            .sender()
            .ok_or_else(|| zbus::fdo::Error::AccessDenied("missing D-Bus sender".into()))?;
        let proxy = DBusProxy::new(connection)
            .await
            .map_err(|e| zbus::fdo::Error::Failed(format!("credential lookup unavailable: {e}")))?;
        let uid = proxy
            .get_connection_unix_user(sender.clone().into())
            .await
            .map_err(|e| zbus::fdo::Error::Failed(format!("credential lookup failed: {e}")))?;
        if uid != 0 {
            return Err(zbus::fdo::Error::AccessDenied(
                "unified execution requires the bridge uid".into(),
            ));
        }
        Ok(())
    }
}

#[interface(name = "org.dbusmcp.Agent")]
impl UnifiedExecutionService {
    async fn execute_catalog(
        &self,
        request_json: String,
        #[zbus(connection)] connection: &Connection,
        #[zbus(header)] header: Header<'_>,
    ) -> zbus::fdo::Result<String> {
        Self::require_root(connection, &header).await?;
        if request_json.len() > 256 * 1024 {
            return Err(zbus::fdo::Error::InvalidArgs(
                "catalog execution request exceeds 256KiB".into(),
            ));
        }
        let request: CatalogExecutionRequest = serde_json::from_str(&request_json)
            .map_err(|e| zbus::fdo::Error::InvalidArgs(format!("invalid catalog request: {e}")))?;
        if request.actor_id.is_empty()
            || request.session_id.is_empty()
            || request.session_genesis.is_empty()
            || !request.arguments.is_object()
        {
            return Err(zbus::fdo::Error::InvalidArgs(
                "catalog attribution and object arguments are required".into(),
            ));
        }
        if !matches!(
            request.agent_type.as_str(),
            "python-executor"
                | "rust-executor"
                | "javascript-executor"
                | "go-executor"
                | "shell-executor"
        ) {
            return Err(zbus::fdo::Error::InvalidArgs(
                "agent is outside the canonical execution catalog".into(),
            ));
        }
        let agent = GLOBAL_REGISTRY
            .get_normalized(&request.agent_type)
            .ok_or_else(|| zbus::fdo::Error::InvalidArgs("unknown execution agent".into()))?;
        if agent.category() != AgentCategory::Execution || !agent.can_handle(&request.operation) {
            return Err(zbus::fdo::Error::InvalidArgs(
                "unsupported execution agent operation".into(),
            ));
        }
        let response = agent
            .execute(AgentRequest {
                operation: request.operation.clone(),
                args: simd_json::serde::to_owned_value(&request.arguments).map_err(|e| {
                    zbus::fdo::Error::InvalidArgs(format!("invalid arguments: {e}"))
                })?,
                context: Some(format!(
                    "actor={} session={} genesis={}",
                    request.actor_id, request.session_id, request.session_genesis
                )),
                files: Vec::new(),
            })
            .await;
        if !response.success {
            return Err(zbus::fdo::Error::Failed(response.message));
        }
        let data = serde_json::to_value(response.data)
            .map_err(|e| zbus::fdo::Error::Failed(format!("invalid executor response: {e}")))?;
        let exit_code = data
            .get("exit_code")
            .and_then(serde_json::Value::as_i64)
            .ok_or_else(|| zbus::fdo::Error::Failed("executor returned no exit status".into()))?;
        let stdout = data
            .get("stdout")
            .or_else(|| data.get("output"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let stderr = data
            .get("stderr")
            .or_else(|| data.get("errors"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        serde_json::to_string(&catalog_execution_result(
            &request.agent_type,
            &request.operation,
            stdout,
            stderr,
            exit_code,
        ))
        .map_err(|e| zbus::fdo::Error::Failed(format!("response serialization failed: {e}")))
    }
}

pub async fn start_unified_execution_service(
    bus_type: BusType,
) -> Result<Connection, DbusAgentError> {
    let connection = match bus_type {
        BusType::System => {
            Builder::system()?
                .name(UnifiedExecutionService::SERVICE_NAME)?
                .serve_at(
                    UnifiedExecutionService::OBJECT_PATH,
                false,
            ),
        },
        "go-executor" => match operation {
            "run" => declaration::<GoRunInput, CatalogExecutionOutput>(
                agent,
                operation,
                SideEffect::Mutation,
                false,
            ),
            _ => declaration::<RustPathInput, CatalogExecutionOutput>(
                agent,
                operation,
                SideEffect::Mutation,
                false,
            ),
        },
        "shell-executor" => declaration::<ShellInput, CatalogExecutionOutput>(
            agent,
            operation,
            SideEffect::Mutation,
            false,
        ),
        _ => panic!("unsupported execution agent in canonical catalog: {agent}"),
    }
}

fn orchestration_decl(agent: &str, operation: &str) -> MethodDecl {
    match operation {
        "run" | "run_workflow" => declaration::<CatalogWorkflowInput, CatalogWorkflowRunOutput>(
            agent,
            operation,
            SideEffect::Mutation,
            false,
        ),
        "list_steps" | "list" => declaration::<CatalogWorkflowInput, CatalogWorkflowListOutput>(
    #[test]
    fn execution_requires_exit_code() {
        assert!(child_success("execution", &json!({"stdout":"ok"})).is_err());
    }

    #[test]
    fn non_execution_success_field_is_supported() {
        assert!(child_success("orchestration", &json!({"success":true})).unwrap());
        assert!(!child_success("orchestration", &json!({"success":false})).unwrap());
    }

    #[test]
    fn empty_workflow_is_invalid() {
        let steps = Vec::new();
        let report = validate("code-review-orchestrator", Some(&steps)).unwrap();
        assert_eq!(report["valid"], false);
        assert_eq!(report["errors"][0]["code"], "empty_workflow");
    }

    #[test]
    fn nested_workflow_target_is_rejected() {
        let steps = vec![json!({
            "agent_type": "code-review-orchestrator",
            "operation": "run_workflow",
            "arguments": {"steps": []}
        })];
        let error =
            validate("code-review-orchestrator", Some(&steps)).unwrap()["errors"][0]["message"]
                .as_str()
                .unwrap()
                .to_string();
        assert!(error.contains("nested orchestration"), "{error}");
    }

    #[test]
    fn forbidden_delegated_target_is_rejected() {
        let steps = vec![json!({
            "agent_type": "shell-executor",
            "operation": "exec",
            "arguments": {"command": "true", "cwd": ".", "timeout": 1}
        })];
        let error =
            validate("code-review-orchestrator", Some(&steps)).unwrap()["errors"][0]["message"]
                .as_str()
                .unwrap()
                .to_string();
        assert!(error.contains("does not allow"), "{error}");
    }

    #[test]
    fn valid_child_arguments_are_accepted() {
        let steps = vec![json!({
            "agent_type": "python-executor",
            "operation": "lint",
            "arguments": {"path": ".", "fix": false}
        })];
        let report = validate("code-review-orchestrator", Some(&steps)).unwrap();
        assert_eq!(report["valid"], true);
        assert!(report["errors"].as_array().unwrap().is_empty());
    }


message GetStateRequest {
  string plugin_id = 1;
  string object_path = 2;
}

message GetStateResponse {
  google.protobuf.Struct state = 1;
  string effective_hash = 2;
  uint64 at_event_id = 3;
  // Exact selected JSON value. Present also for scalar/array/null descendants;
  // state remains populated for object clients. Value numbers retain the
