    id: &'static str,
    name: &'static str,
    domain: &'static str,
    description: &'static str,
    capability: AgentCapability,
) -> Box<dyn UnifiedAgent> {
    let prompt = PERSONA_AGENT
        .replace("{agent_name}", name)
        .replace("{domain}", domain)
        .replace("{expertise_list}", description);
    let knowledge = BASE_AGENT
